.ds-field { display:flex; flex-direction:column; min-width:0; gap:5px; color:var(--muted,#526c79); font-size:12px; line-height:17px }
.ds-field>span:first-child { font-weight:500 }
.ds-input,.ds-select { width:100%; min-width:0; min-height:36px; padding:7px 10px; background:var(--surface,#ffffff); border:1px solid var(--control-line,#78929f); border-radius:7px; color:var(--ink,#142b36); font-size:13px; line-height:20px; caret-color:var(--action,#075672) }
.ds-input[type=number] { font-variant-numeric:tabular-nums }
.ds-input[aria-invalid=true] { border-color:var(--danger,#a12a29) }
.ds-input-unit { display:block; position:relative; min-width:0 }
.ds-input-unit .ds-input { padding-right:34px }
.ds-input-unit .ds-input::-webkit-inner-spin-button { appearance:none; margin:0 }
.ds-input-unit>small { position:absolute; top:50%; right:10px; transform:translateY(-50%); font-size:10px; pointer-events:none }.ds-field,.ds-input{font-family:'PinIt Sans','Segoe UI',sans-serif}.ds-input:focus-visible{outline:3px solid var(--focus,#064c68);outline-offset:3px}

.ds-button { display:inline-flex; align-items:center; justify-content:center; gap:7px; min-height:36px; padding:7px 11px; border:1px solid var(--line,#d7e2e7); border-radius:7px; color:var(--ink,#142b36); background:var(--surface,#ffffff); font-size:12px; font-weight:600; line-height:20px; cursor:pointer; transition:transform 120ms var(--ease-out,cubic-bezier(.23,1,.32,1)),background-color 150ms ease }
