.ds-design-row.ds-selected { background:var(--panel,#e7f3f7); border-color:var(--accent,#4ba6c2) }
.ds-design-select { display:flex; justify-content:flex-start; gap:8px; padding:0; min-width:0; min-height:40px; border:0; background:transparent; text-align:left; flex:1 }
.ds-design-select:active:not(:disabled) { transform:none }
.ds-design-select img,.ds-missing-thumb { display:grid; place-items:center; flex:none; width:36px; height:36px; object-fit:cover; border-radius:5px; background:white }
.ds-missing-thumb { color:var(--danger,#a12a29); background:var(--danger-soft,#fff0ec); font-size:10px }
.ds-missing-thumb small { font-size:9px }
.ds-design-copy { display:flex; flex-direction:column; gap:1px; min-width:0 }
.ds-design-copy strong { font-size:11px; line-height:17px; font-weight:600; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:116px }
.ds-design-copy small { color:var(--muted,#526c79); font-size:10px }.ds-design-row{font-family:'PinIt Sans','Segoe UI',sans-serif}@media(hover:hover) and (pointer:fine){.ds-design-select:hover:not(:disabled),.ds-dock-button:hover:not(:disabled) { background:transparent }}

.ds-brand-symbol { display:block; width:34px; height:34px; overflow:hidden; padding:5px; background:var(--accent,#4ba6c2); border-radius:8px; flex:none }
.ds-block-studs { display:grid; grid-template-columns:repeat(4,1fr); gap:8px; color:var(--accent,#4ba6c2) }
.ds-block-studs>span { display:block; aspect-ratio:1; border-radius:50%; background:linear-gradient(145deg,rgba(255,255,255,.4),rgba(255,255,255,0) 60%),currentColor; box-shadow:1px 2px 3px rgb(4 58 78 / 22%),inset 1px 1px 1px rgb(255 255 255 / 45%) }
.ds-brand-symbol .ds-block-studs { grid-template-columns:repeat(2,1fr); gap:4px }.ds-brand-symbol{box-sizing:border-box}

.ds-floating-dock { position:relative; padding:8px 20px 4px; border-radius:14px; background:white; border:1px solid var(--line,#d7e2e7) }
.ds-floating-dock ul { list-style:none; margin:0; padding:0 }
.ds-dock-slot { position:relative; height:56px; flex:none }
.ds-dock-button { display:flex; flex-direction:column; justify-content:flex-start; width:40px; height:56px; min-height:0; padding:0; gap:4px; border:0; border-radius:7px; color:var(--ink,#142b36); background:transparent; transition:none }
.ds-dock-button:active:not(:disabled) { transform:none }
.ds-dock-tile { display:grid; place-items:center; width:40px; height:36px; flex:none; border-radius:8px; background:var(--workspace,#f1f7f9); color:var(--muted,#526c79); transform-origin:center bottom; will-change:transform }
.ds-dock-tile svg { width:21px; height:21px }
.ds-dock-selected .ds-dock-tile { background:var(--action,#075672); color:white }
.ds-dock-selected .ds-dock-label { color:var(--action,#075672); font-weight:650 }
.ds-dock-label { font-size:10px; line-height:14px; font-weight:500; color:var(--muted,#526c79) }
.ds-dock-button:disabled { border:0; background:transparent; opacity:.5 }
.ds-dock-button:focus-visible { outline:2px solid var(--focus,#064c68); outline-offset:4px }.ds-floating-dock{display:inline-block;font-family:'PinIt Sans','Segoe UI',sans-serif}.ds-floating-dock ul{display:flex;align-items:flex-end;gap:12px}.ds-dock-slot{width:40px}.ds-dock-button{align-items:center;font-family:inherit}@media(hover:hover) and (pointer:fine){.ds-design-select:hover:not(:disabled),.ds-dock-button:hover:not(:disabled) { background:transparent }}
